entries[367614] = { ["name"] = "Verbündetenhandgelenksschützer der Kameradschaft", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nTrophäenhalskette des Zentauren , Obsidianversengte Legierung (8), Funke (#247)\nOptionale Reagenzien:\nBeute von:\nAngriff der Zaqali\nZone:\nAberrus, Schmelztiegel der Schatten\nPläne:\nErhältlich im Auktionshaus\n\nVerbündetenhandgelenksschützer der Kameradschaft\nWird beim Aufheben gebunden\nHandgelenk Platte\n417 Rüstung\n+144 [Stärke oder Intelligenz]+234 Ausdauer\nErhöht Eure kritische Trefferwertung um + 111.\nErhöht Eure Tempowertung um + 158.\nHaltbarkeit 55 / 55\nAnlegen: Gewährt 25 Vielseitigkeit für jeden Verbündeten im Umkreis von 30 Metern. Bis zu 4-mal stapelbar.\n70" }
entries[367615] = { ["name"] = "Verbündetenbrustplatte des Großmuts", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nTrophäenhalskette des Zentauren , Obsidianversengte Legierung (10), Funke (#247)\nOptionale Reagenzien:\nBeute von:\nAngriff der Zaqali\nZone:\nAberrus, Schmelztiegel der Schatten\nPläne:\nErhältlich im Auktionshaus\n\nVerbündetenbrustplatte des Großmuts\nWird beim Aufheben gebunden\nBrust Platte\n834 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\n+ 171 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 307.\nHaltbarkeit 165 / 165\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euch und Eure nächsten 4 Verbündeten innerhalb von 30 Metern für 10 Sek. in einen Siegesrausch zu versetzen, der die Vielseitigkeit um 138 erhöht.\n70" }
entries[367616] = { ["name"] = "Wutentbrannte Kriegsstiefel der Ungesühntheit", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nGroßer robuster Oberschenkelknochen (2), Obsidianversengte Legierung (2), Wutentbrannte Legierung (16), Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\nWutentbrannte Kriegsstiefel der Ungesühntheit\nWird beim Aufheben gebunden\nFüße Platte\n521 Rüstung\n+193 [Stärke oder Intelligenz]+312 Ausdauer\n+ 256 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 102.\nHaltbarkeit 80 / 80\nAnlegen: Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, wird Euer Primärwert 10 Sek. lang um 200 erhöht. Kann nur einmal alle 30 Sek. auftreten.\n70" }
entries[367617] = { ["name"] = "Wutentbrannter Helm der Rache", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nObsidianversengte Legierung (2), Wutentbrannte Legierung (20), Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\nWutentbrannter Helm der Rache\nWird beim Aufheben gebunden\nKopf Platte\n625 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\nErhöht Eure kritische Trefferwertung um + 184.\n+ 294 Vielseitigkeit\nHaltbarkeit 100 / 100\nAnlegen: Gegner, die Euch Schaden zufügen, erleiden manchmal [Quellwert] körperlichen Schaden im Verlauf von 6 Sek.\n70", ["unresolvedValues"] = true }
entries[367618] = { ["name"] = "Instabiler Frostfeuergürtel", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nFrostige Seele , Feurige Seele , Frostfeuerlegierung (13), Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Azurblaues Gewölbe\nPläne:\nErhältlich im Auktionshaus\n\nInstabiler Frostfeuergürtel\nWird beim Aufheben gebunden\nTaille Platte\n469 Rüstung\n+193 [Stärke oder Intelligenz]+312 Ausdauer\nErhöht Eure kritische Trefferwertung um + 256.\nErhöht Eure Meisterschaftswertung um + 102.\nHaltbarkeit 55 / 55\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Gegner mit 'Verbleibender Frostfunke' zu belegen und ihnen [Quellwert] Frostfeuerschaden im Verlauf von 10 Sek. zuzufügen. Gegner, die sterben, während dieser Effekt aktiv ist, explodieren und hinterlassen kalten Graupel, der 8 Sek. lang anhält und Gegner um 50% verlangsamt.\n70", ["unresolvedValues"] = true }
entries[367619] = { ["name"] = "Frostfeuerbeinschützer der Vorbereitung", ["text"] = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nFrostige Seele , Feurige Seele , Frostfeuerlegierung (16), Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Azurblaues Gewölbe\nPläne:\nErhältlich im Auktionshaus\n\nFrostfeuerbeinschützer der Vorbereitung\nWird beim Aufheben gebunden\nBeine Platte\n729 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\nErhöht Eure Tempowertung um + 212.\nErhöht Eure Meisterschaftswertung um + 266.\nHaltbarkeit 120 / 120\nAnlegen: Wenn Ihr einem neuen Gegner Schaden zufügt, wird Euer Tempo für 10 Sek. um 119 erhöht. Bis zu 5-mal stapelbar.\n70" }
entries[367620] = { ["name"] = "Korallenpirscherwellenrochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Rochenart hat sich offensichtlich dazu entwickelt, mitten in bunten Korallenriffen auf ihre Beute zu lauern.\"\nPromotion" }
entries[367621] = { ["name"] = "Ermächtigter tückischer Stern", ["text"] = "300 Meter Reichweite\nSofort\nAnduin entsendet Wellen dunkler Energie, die sich nach außen bewegen und von den Rändern des Kampfbereichs abprallen. Getroffene Spielercharaktere erleiden alle 1 Sek. 34460 Zwielichtschaden und können nicht angreifen oder Zauber wirken. Hält 6 Sek. lang an.\n\nWenn Anduins Diener von 'Tückischer Stern' getroffen werden, werden sie 10 Sek. lang alle 1 Sek. um 5% ihrer maximalen Gesundheit geheilt und sind währenddessen immun gegen Kontrollverlust- und Unterbrechungseffekte." }
