entries[367664] = { ["name"] = "Pflichtgebundener Hammer", ["text"] = "Vergeltung\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Urteil des Templers' löst automatisch 'Göttlicher Sturm' aus.\n\nHeilig\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Licht der Morgendämmerung' aus.\n\nSchutz\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Schild der Rechtschaffenen' aus." }
