entries[367670] = { ["name"] = "Zermürbender Schmerz", ["text"] = "300 Meter Reichweite\nSofort\nDer Prototyp der Absolution schlägt mit enormer Kraft zu, fügt Spielercharakteren und nekrotischen Ritualisten in der Richtung seines aktuellen Ziels 93982 Schattenschaden zu und erhöht ihren erlittenen Schaden 40 Sek. lang um 25%. Dieser Effekt ist stapelbar." }
entries[367673] = { ["name"] = "Herzgebundener Lupin", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Vom Moment seiner Schöpfung an hat dieser rudellose Lupin nichts anderes als tiefste Zuneigung und Loyalität für Euch empfunden.\"\nBeruf:\nProtoformsynthese" }
entries[367676] = { ["name"] = "Nethergesättigter Großwyrm", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur wenige Manawyrms finden Quellen arkaner Macht, die so ergiebig sind, dass ein Wyrm eine solche Größe erreichen kann. Großwyrms haben einen unvergleichlichen Manahunger.\"\nWoW-Shop" }
