entries[367826] = { ["name"] = "Wilde grüne Kampfschildkröte", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare wilde grüne Kampfschildkröte oder gibt sie wieder frei. Dieses Reittier ist an Land nicht besonders flink, schwimmt aber dafür schnell. Und es hat Kanonen.\n\"Eure Schildkröte ist zu langsam, um Eure Feinde einzuholen? Fügt Kanonen hinzu. Niemand kann einer Kanonenkugel entkommen.\"\nHandelsposten" }
