entries[367885] = { ["name"] = "Zudringlicher Gedankenkäfig", ["text"] = "30 Meter Reichweite\nSofort 3 min Abklingzeit\nErschafft eine Verbindung tief in den Gedanken Eures Ziels, die Euer Ausweichen um 179 erhöht und ihm im Verlauf von 6 Sek. [Quellwert] Gesundheit entzieht.\n\nWenn die Verbindung bei Ablauf des Effekts noch intakt ist, zersplittern die Gedanken des Ziels, was Gegnern innerhalb von 8 Metern um das Ziel 841 Schattenschaden zufügt und sie für 3 Sek. entsetzt.", ["unresolvedValues"] = true }
