entries[367901] = { ["name"] = "Flüchtiges Säckchen", ["text"] = "Ca. 4.5 Procs pro Minute\nEure Nahkampfangriffe und -fähigkeiten haben eine hohe Chance, ein flüchtiges Säckchen an Eurem Ziel zu befestigen. Beim Erreichen von 3 Stapeln oder bei Entfernung explodiert das flüchtige Säckchen und verursacht ( 1 * 6636 ) Feuerschaden." }
