entries[367910] = { ["name"] = "Resonante Wut", ["text"] = "Animabonus\nSofort\nWenn Pocopoc einen kernlosen Vombata übernimmt, hat er eine Chance, beim Töten einen Kampfrauscheffekt mit einer Dauer von 8 Sek. einzusetzen." }
