entries[367914] = { ["name"] = "Resonantes Nachwachsen", ["text"] = "Animabonus\nSofort\nWenn Pocopoc einen kernlosen Geomentar übernimmt, baut er regelmäßig wiederherstellende Schilde um Euch auf. Der Schild zerspringt beim Erleiden von Schaden und stellt 5% Eurer maximalen Gesundheit wieder her. Bis zu 3-mal stapelbar." }
entries[367918] = { ["name"] = "Ascheweihung", ["text"] = "Pakt-Fähigkeit\n20% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 4 min Abklingzeit\nWeiht den Zielbereich für 30 Sek. Gegner innerhalb des Bereichs erleiden bis zu [(55% der Zaubermacht) * 30 / 5.19999981] Schattenschaden und Verbündete werden um bis zu [(36% der Zaubermacht) * 30 / 5.19999981] Gesundheit geheilt. Die Werte verringern sich bei mehr als 0 Zielen.\n\nInnerhalb der Weihung könnt Ihr 'Hammer des Zorns' gegen jedes beliebige Ziel einsetzen und die Fähigkeit verursacht 100% mehr Schaden." }
