entries[367924] = { ["name"] = "Grimmige Finsternis", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nManifestiert einen Quasar, der Euer Ziel umkreist und ihm im Verlauf von 7 Sek. 2794 kosmischen Schaden zufügt.\n\nNach 7 Sek. stabilisiert sich der Quasar und erschafft einen Ereignishorizont, der 10 Sek. lang anhält und Euch innerhalb seines Effektbereichs 257 Tempo gewährt." }
entries[367929] = { ["name"] = "Narben der brüderlichen Zwietracht", ["text"] = "Befestigt eine Rune der Herrschaft an Euch, die Euch Macht gewährt... zu einem gewissen Preis." }
entries[367930] = { ["name"] = "Narben der brüderlichen Zwietracht", ["text"] = "Sofort 30 sek. Abklingzeit\nFügt eine weitere hinzu." }
entries[367931] = { ["name"] = "Ketten der Herrschaft", ["text"] = "15 Meter Reichweite\nSofort 3 min Abklingzeit\nRammt einen Stachel in Euer Ziel, der 5489 körperlichen Schaden verursacht und für 20 Sek. eine Kettenverbindung zwischen Euch schafft. Solange die Kette besteht, werden 25% des dem Ziel zugefügten Schadens in ihr gespeichert, bis zu maximal 2329 Schaden.\n\nWenn Ihr Euch von Eurem Ziel entfernt, wird die Kette herausgerissen und die gespeicherte Schadensmenge wird allen Gegnern innerhalb von 8 Metern um das Ziel als Schattenschaden zugefügt." }
entries[367932] = { ["name"] = "Düsteres Schicksal", ["text"] = "300 Meter Reichweite\nSofort\nWenn sie besiegt werden, ermächtigen düstere Reflexionen alle verbleibenden Reflexionen und erhöhen deren Tempo um 150%." }
entries[367937] = { ["name"] = "Resonante Wut", ["text"] = "Wirken in 3 sek.\nWenn Pocopoc einen kernlosen Vombata übernimmt, hat er eine Chance, beim Töten einen Kampfrauscheffekt mit einer Dauer von 8 Sek. einzusetzen.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
entries[367938] = { ["name"] = "Resonantes Gespinst", ["text"] = "Wirken in 3 sek.\nWenn Pocopoc einen kernlosen Tarachniden übernimmt, gewährt Euch dies eine Chance, Nahkampfangreifer zu betäuben und zu vergiften.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
entries[367939] = { ["name"] = "Resonanter Panzer", ["text"] = "Wirken in 3 sek.\nWenn Pocopoc einen kernlosen Skarabiden übernimmt, verringert das Euren erlittenen Schaden um 10%.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
entries[367940] = { ["name"] = "Resonanter Schleim", ["text"] = "Wirken in 3 sek.\nWenn Pocopoc einen kernlosen Heliciden übernimmt, hat er eine Chance, bei Angriffen das Angriffs- und Zaubertempo des Gegners zu verringern.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
entries[367941] = { ["name"] = "Resonantes Nachwachsen", ["text"] = "Wirken in 3 sek.\nWenn Pocopoc einen kernlosen Geomentar übernimmt, baut er regelmäßig wiederherstellende Schilde um Euch auf. Der Schild zerspringt beim Erleiden von Schaden und stellt 5% Eurer maximalen Gesundheit wieder her. Bis zu 3-mal stapelbar.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
entries[367949] = { ["name"] = "Seismische Beben" }
entries[367950] = { ["name"] = "Hoffnung des Löwen", ["text"] = "Ca. 20 Procs pro Minute\nEure Zauber haben eine Chance, Hoffnung zu gewähren, was Euren Intelligenz für 12 Sek. um 17 erhöht. Ihr habt eine größere Chance, Hoffnung zu erhalten, wenn Ihr Verbündete oder Gegner mit niedriger Gesundheit als Ziel wählt." }
entries[367951] = { ["name"] = "Verzweiflung des Überrests", ["text"] = "Ca. 20 Procs pro Minute\nEure Schaden verursachenden Zauber haben eine Chance, Eure Gegner mit Verzweiflung zu belegen, was den Effekt Eurer Krankheiten bei ihnen für 12 Sek. um 46 erhöht. Ihr habt eine größere Chance, Verzweiflung hervorzurufen, wenn Ihr Gegner mit höherer Gesundheit angreift." }
entries[367952] = { ["name"] = "Höchste Singularität", ["text"] = "Eure Offensivzauber bauen Stapel von 'Singularität' auf, was Euch pro Stapel 5 Vielseitigkeit und Geschwindigkeit gewährt, bis zu 20.\n\nSobald Ihr 20 erreicht, werden diese Boni verdoppelt und halten 20 Sek. lang an. Nach Ablauf verliert Ihr alle Stapel und müsst 40 Sek. lang warten, bevor Ihr erneut 'Singularität' aufbauen könnt.\n(100ms Abklingzeit)" }
entries[367953] = { ["name"] = "Verdrehtes Richturteil", ["text"] = "30 Meter Reichweite\nSofort 4 min Abklingzeit\nEntfernt die Seele Eures Ziels, sodass das letzte Urteil über sie gefällt werden kann.\n\nDas Besiegen dieser Seele schickt sie in das Nachleben, das sie wirklich verdient, und gewährt Euch für 60 Sek. einen verdrehten Segen, der von ihrem jeweiligen Nachleben abhängt." }
entries[367954] = { ["name"] = "Erntezeit", ["text"] = "Sofort\nEure Diener verursachen 10% mehr Schaden. Wenn der Sekundäreffekt von 'Seelenernter' ausgelöst wird, wird dieser Bonus 8 Sek. lang auf 50% erhöht." }
