entries[367979] = { ["name"] = "Smaragdblüte", ["text"] = "3% von Grundmana 25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLässt eine Knolle aus dem Smaragdgrünen Traum an der Position eines Verbündeten sprießen. Nach 1.5 Sek. heilt diese bis zu 3 verletzte Verbündete innerhalb von 10 Metern um (187.5% der Zaubermacht) Gesundheit." }
entries[367980] = { ["name"] = "Tiefer Atem", ["text"] = "50 Meter Reichweite\nSofort\nAtmet tief ein, fliegt zum Zielort und speit dabei geschmolzene Schlacke unter Euch, die Gegnern in Eurer Bahn (400% der Zaubermacht) Vulkanschaden zufügt.\n\nEntfernt alle Bewegungsunfähigkeitseffekte. Im Flug seid Ihr immun gegen bewegungseinschränkende Effekte und Kontrollverlusteffekte. [ Sande der Zeit : Erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 5 Sek ]" }
entries[367982] = { ["name"] = "Sicherheitsmaßnahmen überbrücken", ["text"] = "Wirken in 1.5 sek.\nDeaktiviert die Schutzvorrichtungen am sehr wertvollen Schatz." }
