entries[368020] = { ["name"] = "Desintegrationskranz", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Ring aus Energie dehnt sich von allen beherrschten Reservoirs aus. Wenn ein Spielercharakter den Ring durchquert, fügt dieser ihm 31327 Schattenschaden sowie allen Verbündeten innerhalb von 1.5 Metern 104424 Schattenschaden zu.\n\nVerursacht zusätzlich alle 1 Sek. 9398 Schattenschaden und erhöht den durch ' Desintegrationskranz ' erlittenen Schaden um 500%. Hält 6 Sek. lang an." }
