entries[368583] = { ["name"] = "Kettenernte", ["text"] = "Sofort\nSchleudert eine Animawelle auf das Ziel, die auf weitere Ziele in der Nähe überspringt. Fügt bis zu 5 Gegnern (205% der Zaubermacht) Schattenschaden zu und heilt bis zu 5 Verbündete um (315% der Zaubermacht) Gesundheit.\n\nDie Abklingzeit von 'Kettenernte' wird pro kritisch getroffenem Ziel um 5 Sek. verringert. [ Meisterschaft: Elementarüberladung : Erzeugt pro getroffenem oder geheiltem Ziel 3 Mahlstrom ]" }
