entries[368585] = { ["name"] = "Duft der Seelen", ["text"] = "100 Meter Reichweite\nSofort\nEure Schadensfähigkeiten haben eine hohe Chance, den Duft köstlicher Seelenenergie auszumachen. Bis zu 100-mal stapelbar. Bei maximalen Stapeln bricht ein Schwarm Verschlinger hervor, die Euer Ziel beißen und ihm so 5120 körperlichen Schaden zufügen.\n\nEffekte, durch die sich Euer Ziel bewegt, erzeugen Bonusstapel.\n(5s Abklingzeit)" }
