entries[368684] = { ["name"] = "Zurückgewinnen", ["text"] = "Sofort\nHalondrus aktiviert einen Schild, der Schaden in Höhe von 4% seiner maximalen Gesundheit absorbiert.\n\nSolange der Schild hält, verursacht Halondrus alle 1 Sek. 12531 kosmischen Schaden und zieht Spielercharaktere sowie Ephemera zu seiner Position. Dieser Effekt wird mit der Zeit stärker." }
entries[368685] = { ["name"] = "Urzeitliche Macht", ["text"] = "Sofort\nNachdem Ihr 10-mal offensive Fähigkeiten eingesetzt habt, verursachen Eure nächsten 3 Einsätze offensiver Fähigkeiten zusätzlich 0% Schaden." }
entries[368686] = { ["name"] = "Urzeitliches Potenzial", ["text"] = "'Furorfäuste' ermächtigt Eure nächsten 3 Angriffe, die als Comboschlag in Frage kommen, sodass sie 15% mehr Schaden verursachen.\n(1s Abklingzeit)" }
entries[368687] = { ["name"] = "Gunst der Ewigen", ["text"] = "100 Meter Reichweite\nSofort\nVor den Ewigen weinend, verschreibt Ihr Euch ihren Diensten.\n\nErhöht Euren höchsten Sekundärwert um 36 und gewährt allen Gruppenmitgliedern, die ebenfalls Eurem Pakt dienen, 10% dieses Bonus." }
