entries[368689] = { ["name"] = "Hoffnung des Löwen", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber haben eine Chance, Hoffnung zu gewähren, was Eure Intelligenz für 0 Sek. um 0 erhöht. Ihr habt eine größere Chance, Hoffnung zu erhalten, wenn Ihr Verbündete oder Gegner mit niedriger Gesundheit als Ziel wählt." }
entries[368690] = { ["name"] = "Verzweiflung des Überrests", ["text"] = "40 Meter Reichweite\nSofort\nEure Schaden verursachenden Zauber haben eine Chance, Eure Gegner mit Verzweiflung zu belegen, was den Effekt Eurer Krankheiten bei ihnen für 0 Sek. um 0 erhöht. Ihr habt eine größere Chance, Verzweiflung hervorzurufen, wenn Ihr Gegner mit höherer Gesundheit angreift." }
entries[368691] = { ["name"] = "Zurückgewinnen", ["text"] = "Sofort\nDer Rückgewinner verankert sich im Boden, wird so unbeweglich, zieht alle Spielercharaktere heran und verursacht 0 kosmischen Schaden. Weiter von seiner Position entfernte Spielercharaktere erleiden weniger Schaden." }
