entries[368744] = { ["name"] = "Seismische Beben", ["text"] = "Unbegrenzte Reichweite\nSofort\nHalondrus erzeugt Beben, die Spielercharakteren innerhalb von 6 Metern 208848 körperlichen Schaden zufügen.\n\nAm Endpunkt jedes Bebens entsteht ein Vorkommen von ' Ephemerer Riss '." }
entries[368746] = { ["name"] = "Seismische Ladung", ["text"] = "200 Meter Reichweite\nSofort\nDer Leidensschmied schleudert seinen Hammer auf sein aktuelles Ziel, fügt ihm 167734 körperlichen Schaden zu und belegt es mit ' Geschwärzte Rüstung '. Flammen brechen vom Einschlagsort aus und fügen allen anderen Spielercharakteren 119810 Feuerschaden zu. Weiter vom Ziel entfernte Spielercharaktere erleiden weniger Schaden.\n\nVon der Position des Ziels bewegen sich Stachelwellen nach außen." }
entries[368747] = { ["name"] = "Pulsierender Kluftsplitter", ["text"] = "100 Meter Reichweite\nSofort\nPlatziert ein Rissportal vor Euch, das sich 1.5 Sek. lang auflädt und dann [ 1553 * (1 + Vielseitigkeit)] kosmischen Schaden in einer Linie auf alle Gegnern aufteilt. Das Portal stiehlt von der Realität an sich, wodurch Ihr einen Schild erhaltet, der 20 Sek. lang anhält und [ 3586 * (1 + Vielseitigkeit)] Schaden absorbiert.\n\nDer Schaden und die Absorption werden für jeden getroffenen Gegner erhöht, für bis zu 5 Gegner." }
