entries[368750] = { ["name"] = "Dissonanzkaskade", ["text"] = "500 Meter Reichweite\nSofort\nWenn sie nicht sowohl melodische als auch harmonische Ausrichtungen umfasst, fügt die Kaskade stattdessen allen Spielercharakteren innerhalb von 4 Metern um das Ziel 939817 kosmischen Schaden zu." }
entries[368751] = { ["name"] = "Resonanzkaskade", ["text"] = "500 Meter Reichweite\nSofort\nLihuvim erschafft eine kosmische Resonanz an der Position eines Spielercharakters, was allen Spielercharakteren innerhalb von 4 Metern um das Ziel 1044 kosmischen Schaden zufügt.\n\nWenn dieser Zauber nicht sowohl melodische als auch harmonische Ausrichtungen trifft, entsteht stattdessen eine 'Dissonanzkaskade'." }
