entries[368896] = { ["name"] = "Erneuerter Protodrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren erneuerten Protodrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n\"Als die Inseln erwachen, antworten diese Protodrachen auf den Ruf, an der Seite der Sterblichen durch die Lüfte zu segeln.\"\nErfolg:\nDracheninseln: Ein neuer Freund" }
